-- Lindenmoor import, Task 1: a read-only survey of Ye (placeId 106992859583940). Run in Edit through the bridge:
--   python -I Art/Tools/rbxc.py luau "placeId: 106992859583940" Edit @Art/Studio/Regions/Lindenmoor/survey_ye.lua
-- It changes nothing in the place except ServerStorage.LMSurvey, a StringValue holding the survey JSON (the bridge
-- prints only 30k characters). run_survey.py runs it, reads it back in 25k chunks, writes ye_survey.json and removes
-- LMSurvey: python -I Art/Studio/Regions/Lindenmoor/run_survey.py. Checked by check_survey.py.
-- The INFILL literal is generated by `python -I check_survey.py --stamp survey_ye.lua` from layout.json's Infill rect
-- minus its Keep (4-stud world cells, Art/Blender/lindenmoor/expansion_plan.keep_mask(), the plan's own mask).
local HttpService = game:GetService("HttpService")
local CS = game:GetService("CollectionService")
local ServerStorage = game:GetService("ServerStorage")

-- INFILL BEGIN
local INFILL = "[[-392,-1004,-288],[-388,-1004,-288],[-384,-1004,-288],[-380,-1004,-288],[-376,-1004,-288],[-372,-1004,-288],[-368,-1004,-288],[-364,-1004,-288],[-360,-1004,-288],[-356,-1004,-288],[-352,-1004,-288],[-348,-1004,-288],[-344,-1004,-288],[-340,-1004,-288],[-336,-1004,-988],[-336,-296,-288],[-332,-1004,-988],[-332,-296,-288],[-328,-1004,-988],[-328,-296,-288],[-324,-1004,-988],[-324,-296,-288],[-320,-1004,-988],[-320,-296,-288],[-316,-1004,-988],[-316,-296,-288],[-312,-1004,-988],[-312,-296,-288],[-308,-1004,-988],[-308,-296,-288],[-304,-1004,-988],[-304,-296,-288],[-300,-1004,-988],[-300,-296,-288],[-296,-1004,-988],[-296,-296,-288],[-292,-1004,-988],[-292,-296,-288],[-288,-1004,-988],[-288,-296,-288],[-284,-1004,-988],[-284,-296,-288],[-280,-1004,-988],[-280,-296,-288],[-276,-1004,-988],[-276,-296,-288],[-272,-1004,-988],[-272,-296,-288],[-268,-1004,-988],[-268,-296,-288],[-264,-1004,-988],[-264,-296,-288],[-260,-1004,-988],[-260,-296,-288],[-256,-1004,-988],[-256,-296,-288],[-252,-1004,-988],[-252,-296,-288],[-248,-1004,-988],[-248,-296,-288],[-244,-1004,-988],[-244,-296,-288],[-240,-1004,-988],[-240,-296,-288],[-236,-1004,-988],[-236,-296,-288],[-232,-1004,-988],[-232,-296,-288],[-228,-1004,-988],[-228,-296,-288],[-224,-1004,-988],[-224,-296,-288],[-220,-1004,-988],[-220,-296,-288],[-216,-1004,-988],[-216,-296,-288],[-212,-1004,-988],[-212,-296,-288],[-208,-1004,-988],[-208,-296,-288],[-204,-1004,-988],[-204,-296,-288],[-200,-1004,-988],[-200,-296,-288],[-196,-1004,-988],[-196,-296,-288],[-192,-1004,-988],[-192,-296,-288],[-188,-1004,-988],[-188,-296,-288],[-184,-1004,-988],[-184,-296,-288],[-180,-1004,-988],[-180,-296,-288],[-176,-1004,-988],[-176,-296,-288],[-172,-1004,-988],[-172,-296,-288],[-168,-1004,-988],[-168,-296,-288],[-164,-1004,-988],[-164,-296,-288],[-160,-1004,-988],[-160,-296,-288],[-156,-1004,-988],[-156,-296,-288],[-152,-1004,-988],[-152,-296,-288],[-148,-1004,-988],[-148,-296,-288],[-144,-1004,-988],[-144,-296,-288],[-140,-1004,-988